lib='''from collections import Counter

def colors(grid):
    """The grid's colors as a Counter from color to cell count."""
    return Counter(v for row in grid for v in row)

def bg_color(grid):
    """The most common color in the grid."""
    return colors(grid).most_common(1)[0][0]

def rarest_color(grid):
    """The least common color in the grid."""
    return min(colors(grid), key=lambda v: colors(grid)[v])

def cells_of(grid, color):
    """The set of (i, j) positions whose cell has the given color."""
    return {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color}

def normalize(cells):
    """A set of positions shifted so its top-left corner is (0, 0), as a sorted tuple."""
    mi = min(i for i, _ in cells); mj = min(j for _, j in cells)
    return tuple(sorted((i - mi, j - mj) for i, j in cells))

def stamp_copies(grid, shape, color):
    """Recolor to `color` every cell covered by a placement of `shape` (a tuple of
    relative positions) whose cells all share one single other color in the grid."""
    h, w = len(grid), len(grid[0])
    mh = max(i for i, _ in shape); mw = max(j for _, j in shape)
    target = None
    for i in range(h):
